/**
 * Slack (catalog connector — declaration only)
 *
 * Slack is a CHAT platform, not a data feed: inbound traffic is Chat SDK events
 * delivered to the shared app-webhook endpoint, and per-message routing is via
 * `/lobu link` Event Behaviors — NOT a connector `sync()`. This file exists so
 * the Slack app's credentials + install/webhook scheme flow through the SAME
 * declaration-driven resolver as GitHub/Jira/Linear: the gateway reads the
 * declared env-var NAMES here (`SLACK_CLIENT_ID`, `SLACK_CLIENT_SECRET`,
 * `SLACK_SIGNING_SECRET`) instead of hardcoding `process.env.SLACK_*` literals.
 *
 * Declared as `kind: 'integration'` (see {@link IntegrationConnector}): a pure
 * app/auth declaration, deliberately INERT as a catalog entry (see the
 * bundled-connector side-effect audit):
 *  - NO `feeds` → no auto-provisioned data feeds, nothing for device-reconcile
 *    to wire, and the install callback writes only the `app_installations` row.
 *  - NO `runtime` / `requiredCapability` → `getBundledDeviceConnectors()` filters
 *    it out, so it is never auto-installed onto a device fleet.
 *  - NO `sync()` → an integration connector has no syncable feeds; the
 *    `IntegrationConnector` base throws if one is ever scheduled (a wiring bug).
 *
 * The webhook `delivery: 'app_installation'` + `routingKeyPaths` tells the
 * app-webhook router this connector's deliveries route by Slack `team_id` through
 * `/api/v1/app-webhooks/slack`. Verify is FULLY DECLARATIVE — the generic engine
 * computes Slack's `v0:{ts}:{rawBody}` HMAC straight from this schema; there is no
 * Slack-specific verify plugin.
 */

import {
	type ConnectorDefinition,
	IntegrationConnector,
} from "@lobu/connector-sdk";
import { SLACK_BEHAVIOR_EVENTS } from "./slack-behavior-events.js";

/**
 * Bot scopes requested by `/slack/install`. The Slack manifest does not drive
 * that route: the generic install engine reads this connector declaration.
 * Keep this list exactly aligned with the manifest, and never drop
 * `mcp:connect` — without it Slackbot cannot discover Lobu's MCP server.
 */
const SLACK_BOT_SCOPES = [
	"app_mentions:read",
	"assistant:write",
	"channels:history",
	"channels:read",
	"chat:write",
	"chat:write.public",
	"commands",
	"files:read",
	"files:write",
	"groups:history",
	"groups:read",
	"im:history",
	"im:read",
	"im:write",
	"mcp:connect",
	"mpim:history",
	"mpim:read",
	"reactions:read",
	"reactions:write",
	"users:read",
];

/** Bot events the hosted app subscribes to (manifest `bot_events`). */
const SLACK_BOT_EVENTS = [
	"app_home_opened",
	"app_mention",
	"member_joined_channel",
	"message.channels",
	"message.groups",
	"message.im",
	"message.mpim",
	"team_join",
];

export default class SlackConnector extends IntegrationConnector {
  readonly definition: ConnectorDefinition = {
		key: "slack",
		kind: "integration",
		name: "Slack",
    description:
			"Connect a Slack workspace to Lobu. Mention the bot, DM it, or run /lobu in any channel to drive a sandboxed agent.",
		version: "1.0.0",
		behaviorEvents: SLACK_BEHAVIOR_EVENTS,
		faviconDomain: "slack.com",
    webhook: {
      // App-level delivery: one webhook is configured ONCE on the Slack app, and
      // inbound deliveries route via the shared `/api/v1/app-webhooks/slack`
      // endpoint. Slack's signature scheme is FULLY declarative: HMAC-SHA256 over
      // `v0:{timestamp}:{body}` compared against `x-slack-signature` (prefix
      // `v0=`), plus a 300s timestamp-freshness replay guard — the generic engine
      // verifies it with no Slack-specific code.
			delivery: "app_installation",
      // Verified deliveries forward to the chat adapter (the routing chain in
      // SlackConnectionCoordinator), not the data-ingest path. The generic engine
      // dispatches on this, never on the `slack` name.
			deliveryKind: "chat",
			signatureHeader: "x-slack-signature",
			algorithm: "sha256",
			signaturePrefix: "v0=",
			signingBaseTemplate: "v0:{timestamp}:{body}",
			timestampHeader: "x-slack-request-timestamp",
      freshnessSeconds: 300,
      // The team id sits in different places across Slack event shapes; first
      // match wins.
			routingKeyPaths: ["team_id", "team.id", "event.team_id"],
    },
    authSchema: {
      methods: [
        {
					type: "app_installation",
					provider: "slack",
					providerInstance: "cloud",
          // "Add to Slack" is a standard OAuth code exchange: the gateway's
          // generic install engine mounts /slack/install + /slack/oauth_callback,
          // redirects to `authorizeUrl` with the client id + scopes, and on
          // callback exchanges the code at `tokenUrl`. The engine dispatches on
          // this shape, never on the `slack` name.
					installShape: "oauth-code-exchange",
					authorizeUrl: "https://slack.com/oauth/v2/authorize",
					tokenUrl: "https://slack.com/api/oauth.v2.access",
          // The hosted Lobu Slack app's OAuth client (used for the "Add to Slack"
          // install handshake) + the signing secret used to verify inbound
          // events. Declared as env-var NAMES; the gateway resolves the values.
					clientIdKey: "SLACK_CLIENT_ID",
					clientSecretKey: "SLACK_CLIENT_SECRET",
					webhookSecretKey: "SLACK_SIGNING_SECRET",
          permissions: SLACK_BOT_SCOPES,
          events: SLACK_BOT_EVENTS,
          required: false,
          description:
						"Install the Lobu app on your Slack workspace to grant the bot token. Routing to agents is per-channel via /lobu link.",
        },
        {
          // "Sign in with Slack" (OpenID Connect). Fully self-describing: the
          // declaration carries Slack's OIDC endpoints + login scopes, so the
          // gateway wires it through Better Auth's provider-agnostic
          // `genericOAuth` plugin (NOT the built-in `socialProviders` allowlist —
          // Slack is not a Better Auth built-in social provider). Core stays
          // provider-name-free; everything provider-specific lives here. Reuses
          // the SAME hosted Lobu Slack app client as the install method above
          // (env-var NAMES; the gateway resolves the values). Signing in
          // auto-provisions the user's personal org + default agent via Better
          // Auth's `user.create` hook (OIDC `sub` → Slack user id); no data feed.
					type: "oauth",
					provider: "slack",
					loginScopes: ["openid", "email", "profile"],
					authorizationUrl: "https://slack.com/openid/connect/authorize",
					tokenUrl: "https://slack.com/api/openid.connect.token",
					userinfoUrl: "https://slack.com/api/openid.connect.userInfo",
					clientIdKey: "SLACK_CLIENT_ID",
					clientSecretKey: "SLACK_CLIENT_SECRET",
          required: false,
          description:
						"Sign in with Slack to create or access your Lobu account using your Slack identity.",
				},
				{
					type: "none",
					label: "Use your own Slack app",
        },
      ],
    },
		optionsSchema: {
			type: "object",
			"x-lobu-chat-platform": "slack",
			properties: {
				botToken: {
					type: "string",
					format: "password",
					title: "Bot token",
					description:
						"The xoxb- token issued when you install your Slack app.",
				},
				signingSecret: {
					type: "string",
					format: "password",
					title: "Signing secret",
					description: "Used to verify every inbound Slack request.",
				},
			},
			required: ["botToken", "signingSecret"],
		},
  };
}
import { readFileSync } from "node:fs";
import { beforeAll, describe, expect, mock, test } from "bun:test";
import { connectorSdkMock } from "./connector-sdk.mock";

mock.module("@lobu/connector-sdk", connectorSdkMock);

// biome-ignore lint/suspicious/noExplicitAny: dynamic import after shared SDK mock
let SlackConnector: any;

beforeAll(async () => {
	const module = await import("../slack");
	SlackConnector = module.default;
});

describe("Slack connector declaration", () => {
	test("keeps install scopes aligned with the manifest and includes Slackbot MCP", () => {
		const manifest = JSON.parse(
			readFileSync(
				new URL(
					"../../../../config/slack-app-manifest.self-install.json",
					import.meta.url,
				),
				"utf8",
			),
		);
		const connector = new SlackConnector();
		const installMethod = connector.definition.authSchema?.methods.find(
			(method: { type: string }) => method.type === "app_installation",
		);

		expect(installMethod?.permissions).toContain("mcp:connect");
		expect(installMethod?.permissions).toEqual(manifest.oauth_config.scopes.bot);
	});
});
- **ACL = `entity_relationships` edges with explicit effect: `can_read` (allow)
  and `deny_read` (deny)** — deny-wins needs a place to read denies from. `resource
  → audience` principal. Private channel → `can_read` its member-group; public →
  `can_read` the workspace company.
- Boolean ACL **expressions** (Jira `browse AND issue-security`) compile to
  **effective-read principals** (a synthetic intersection principal or a concrete
  member set) — **NEVER** naive `can_read` edges to both groups (that is OR → a
  leak). "Flat principal sets" are safe only because they are *effective-read*
  principals. If a source can't compile to effective principals safely, it's
  `aclSupport: none` ⇒ owner-only (decision 4). Slack needs no expressions
  (membership is already effective).

## 4. The gate (one SQL function, used everywhere) — two-sided, fail-closed
A row is visible iff **ALL** hold (in one SQL function — no caller conventions):
1. **User side:** some `can_read` principal ∈ the viewer `$member` closure AND no
   `deny_read` principal ∈ it (deny wins).
2. **Agent side:** it is within the run's agent/channel scope. The effective
   access is **`user ∩ agent`** — an agent NEVER widens beyond both its own scope
   and the user's. Headless/autonomous agent → empty set.
3. **Freshness:** the source's `freshness_state = fresh` — checked **inside the
   gate SQL**, so missing/unknown/stale ACL state DENIES in the same query.

Viewer closure = `$member` + trusted source identities + transitive `member_of`
(recursive CTE; materialized closure later) + org/public audiences. Returns
visible resource ids → filters `channel_messages` / `events`. Applied uniformly:
`search.ts` recall, RAG, agent tool-calls, feeds route, exports — no bypass.
**Do NOT simply replace the agent-bound-channel fence with the user gate** — that
widens access from "agent's channels" to "all the user's channels"; intersect them.

## 5. Freshness / revocation
Per-source `freshness_state` (fresh|stale|unknown|failed) + `aclSupport`
(full|partial|none) + `strict_mode`. Membership removals are high-priority
invalidation (Slack `member_left_channel`, already-subscribed events + reconcile
job). Bounded SLA (Slack private <30s target; others <1-5min); fail closed when
stale/unknown. Storage: a small `authz_source_acl_state` (org, connection) — the
ONE genuinely-new small table besides provenance.

## 6. Derived-artifact ACLs (AI oversharing)
`derived_artifact_sources(artifact_event_id, source_event_id)` provenance; an
artifact (summary/embedding/memory/cached answer) is visible iff the viewer can
see ALL its sources. Provenance must be **complete + transitive**; **missing,
deleted, stale, or unknown-ACL source → DENY the artifact** (fail closed — partial
provenance is not visibility). RAG: filter candidates → build prompt → revalidate
citations.

## 7. Database changes (minimal — this is the consolidation payoff)
- `entity_identities`: add `assurance` (+ `verified_at`), two-phase (squawk gate).
  [extends existing table]
- `authz_source_acl_state`: small per-(org,connection) freshness/strict-mode row. [new, small]
- `derived_artifact_sources`: provenance for derived artifacts. [new, small]
- `can_read` + `deny_read` relationship types: **data, no migration** (runtime `ensure*Type`).
- Channels/workspaces as entities, memberships, ACL edges: **no migration** (reuse).

Net: **1 column add + 2 small tables** — vs. the 5 new tables the from-scratch
approach implied.

