/** Dependencies the App Home tab needs to render status and run OAuth. */
interface SlackAppHomeDeps {
  /**
   * The initialized Slack adapter — the one with the live `@slack/web-api`
   * client. The adapter handed to event handlers via `event.adapter` is the
   * webhook-dispatch instance and has no `client`, so `publishHomeView` must
   * go through this one.
   */
  adapter?: SlackHomeAdapter;
  /**
   * Public origin of the gateway — since the web SPA is served same-origin,
   * this is the base for the dashboard deep link and preview setup prompt.
   */
  publicGatewayUrl?: string;
  /**
   * Resolves the org dashboard slug + glanceable counts for the home tab.
   * Read-only; failures degrade gracefully to a slug-less dashboard link.
   */
  resolveHomeContext?: (
    organizationId: string,
  ) => Promise<SlackHomeContext | null>;
  /**
   * Resolves the viewing Slack user's personal notification inbox, or null when
   * they have no linked Lobu identity. `teamId` scopes the lookup to the
   * correct Slack workspace and is always a real workspace id — a connection
   * without one is not looked up at all, since a Slack `U…` is only unique
   * within a workspace. Read-only; failures degrade to no inbox.
   */
  resolveUserInbox?: (
    slackUserId: string,
    teamId: string,
  ) => Promise<SlackHomeInbox | null>;
}

/** Trim a trailing slash so we can append `/segment` cleanly. */
function trimTrailingSlash(url: string): string {
  return url.replace(/\/+$/, "");
}

/** Turn a connector key like `apple.screen_time` into `Apple Screen Time`. */
function humanizeSource(platform: string | null): string | null {
  if (!platform) return null;
  return platform.replace(/[._-]+/g, " ").replace(/\b\w/g, (c) =>
    c.toUpperCase(),
  );
}

/** Escape Slack mrkdwn control chars so titles can't inject formatting. */
function escapeMrkdwn(text: string): string {
  return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

/** Render the "Recent activity" list as a single section, or `[]` if empty. */
function recentBlocks(
  recent: SlackHomeRecentItem[],
): Record<string, unknown>[] {
  if (recent.length === 0) return [];
  const lines = recent.map((item) => {
    const title = escapeMrkdwn(item.title);
    const source = humanizeSource(item.platform);
    // `<!date^…>` renders in the viewer's own timezone; the pipe text is the
    // fallback Slack shows if it can't resolve the token.
    const when = `<!date^${item.ts}^{date_short_pretty}|recently>`;
    return source
      ? `• *${title}*  ·  ${escapeMrkdwn(source)}  ·  ${when}`
      : `• *${title}*  ·  ${when}`;
  });
  return [
    {
      type: "section",
      text: { type: "mrkdwn", text: `*Recent activity*\n${lines.join("\n")}` },
    },
    { type: "divider" },
  ];
}

/**
 * The dashboard card: a "Open dashboard" deep link into the web app plus a
 * context line of org-wide counts. Returns `[]` when there's nowhere to link
 * (no public URL), so the home tab still renders without it.

  forwardWebhook(connectionId: string, request: Request): Promise<Response>;
  getRunningChat(connectionId: string): any | undefined;
  listSlackConnections(): Promise<PlatformConnection[]>;
  /**
   * The generic app-installation store. Slack OAuth workspace installs are a
   * thin projection over it (`lobu/stores/slack-installations.ts`) — no bespoke
   * table or store. Resolved lazily so building the coordinator never forces the
   * store to exist; only the install/webhook paths actually need it.
   */
  getAppInstallationStore(): AppInstallationStore;
  /** Secret store for persisting/purging the per-workspace bot token. */
  getSecretStore(): WritableSecretStore;
}

export class SlackConnectionCoordinator {
  constructor(private readonly deps: SlackConnectionCoordinatorDeps) {}

  async findConnectionByTeamId(
    teamId: string
  ): Promise<PlatformConnection | null> {
    const connections = await this.deps.listSlackConnections();
    return (
      connections.find(
        (connection) =>
          connection.metadata?.teamId === teamId &&
          // A stopped BYO connection must not preempt routing — otherwise it
          // shadows an active OAuth install (an `app_installations` row) for the team
          // (matched first → 503, never falling through to the install).
          connection.status !== "stopped"
      ) || null
    );
  }

  /**
   * Resolve the connection that should handle a webhook we could NOT route by
   * team_id (url_verification challenges, events with no extractable team).
   *
   * Only the hosted shared-app / preview connection is a safe default: it is
   * explicitly marked `settings.previewMode === true`, with a global unique
   * index guaranteeing one such connection per platform. Its real workspace id
   * may be persisted for scoped delivery and ACL checks; the explicit marker,
   * not missing identity, distinguishes it from tenant-owned bots. Everything
   * else is tenant-owned — a team-scoped row obviously so, but ALSO a plain
   * org-owned row with empty metadata (a BYO connection created without an
   * OAuth install never gets a `metadata.teamId`, yet still carries that org's
   * bot token). Forwarding an unmatched-team webhook to any tenant-owned row
   * would let one tenant's bot act on (and reply with its own bot token to)
   * another tenant's Slack traffic.
   * `listSlackConnections()` is platform-scoped only (the public `/api/v1/app-webhooks/slack`
   * route carries no org context, so the store's per-tenant predicate doesn't
   * apply) — so we must require the explicit preview marker and otherwise fail
   * closed (return null → handled-by-OAuth-fallback / 503) rather than pick a
   * foreign tenant.
   */
  async getDefaultConnection(): Promise<PlatformConnection | null> {
    const connections = await this.deps.listSlackConnections();
    return (
      connections.find(
        (connection) => connection.settings?.previewMode === true
      ) || null
    );
  }

  async handleAppWebhook(request: Request): Promise<Response> {
    const body = await request.text();
    const contentType = request.headers.get("content-type") || "";
    const teamJoinEvent = parseSlackTeamJoinEvent(body, contentType);
    const teamId = this.extractTeamId(body, contentType);
    // Grid: events for a workspace inside an Enterprise Grid arrive stamped with
    // a SIBLING workspace's `team_id` (not the install's), but carry the shared
    // `enterprise_id`. Captured so path 2 can fall back to an enterprise match
    // when the exact team id misses.
    const enterpriseId = this.extractEnterpriseId(body, contentType);

    // App/token removal: Slack invalidated the bot token, so stop the matching
    // install(s) BEFORE any routing — a still-`active` row would keep routing
    // events to a dead token and fail every forward. Ack 200 either way (a
    // non-2xx makes Slack retry the uninstall). Handled here (not per-connection)
    // because an org-wide uninstall carries only the enterprise id, no team id.
    if (isSlackUninstallEvent(body, contentType)) {
      const store = this.deps.getAppInstallationStore();
      const stopped = await revokeSlackInstallsForUninstall(store, {
        teamId,
        enterpriseId,
      });
      logger.info(
        { teamId, enterpriseId, stopped },
        "Slack app_uninstalled — stopped install(s)",
      );
      return new Response("", { status: 200 });
    }

    if (teamId) {
      // 1) A BYO agent-owned Slack connection for this workspace (created via
      //    the UI with its own bot token) — unchanged legacy path.
      const connection = await this.findConnectionByTeamId(teamId);
      if (connection) {
        if (!(await this.deps.ensureConnectionRunning(connection.id))) {
          return new Response("Slack connection unavailable", { status: 503 });
        }
        const response = await this.deps.forwardWebhook(
          connection.id,
          this.cloneRequestWithBody(request, body)
        );
        if (response.ok && teamJoinEvent) {
          await this.handleTeamJoinWelcome(connection.id, teamJoinEvent);
        }
        return response;
      }
    }

    // Enterprise Grid interactive payloads can omit `team` entirely and carry
    // only the enterprise id. Keep BYO routing team-scoped above, but allow the
    // managed-install and pending-install paths to resolve that org-wide key.
    const installTenantId = teamId ?? enterpriseId;
    if (installTenantId) {
      // 2) An OAuth-installed workspace (the "Add to Slack" path). The install
      //    is an `app_installations` row (provider=slack), not a BYO `connections` chat row;
      //    the manager hydrates an agentless Slack instance from it (the
      //    `slackinst-` id is namespaced, so `ensureConnectionRunning`/
      //    `forwardWebhook` resolve it via the Slack install projection). Per-message
      //    routing is via `/lobu link` bindings.
      const store = this.deps.getAppInstallationStore();
      // Routing precedence for both install models:
      //  a) EXACT team id — a per-workspace install (Grid or standalone) whose
      //     own workspace homes this event.
      );
    }

    return {
      platform: "slack",
      signingSecret,
      ...(botToken ? { botToken } : {}),
      ...(clientId ? { clientId } : {}),
      ...(clientSecret ? { clientSecret } : {}),
      ...(encryptionKey ? { encryptionKey } : {}),
      ...(installationKeyPrefix ? { installationKeyPrefix } : {}),
      ...(userName ? { userName } : {}),
    };
  }

  /**
   * Reply to a user in an unclaimed workspace with the connect link, using the
   * pending install's bot token. Only responds to a real @mention or DM — never
   * to challenges, retries, or the bot's own messages — and always acks 200 so
   * Slack doesn't retry (and so we never double-post).
   */
  private async replyUnclaimedWorkspace(
    botToken: string,
    teamId: string,
    body: string,
    contentType: string,
    isRetry: boolean,
  ): Promise<Response> {
    const ack = new Response("", { status: 200 });
    if (isRetry) return ack;
    const event = parseSlackUserMessageEvent(body, contentType);
    if (!event) return ack;
    const webBase = getConfiguredPublicOrigin()?.replace(/\/+$/, "");
    if (!webBase) return ack;
    const claimUrl = `${webBase}/connector/slack/connection?ref=${encodeURIComponent(teamId)}`;
    const text = `👋 This Slack installation isn't connected to a Lobu organization yet. A workspace admin can <${claimUrl}|choose its Lobu organization>. Using Lobu's hosted Slack workspace instead? Leave this installation unconnected, open the workspace link from \`lobu run\`, and run the shown \`/lobu link CODE\` command there.`;
    try {
      await createSlackWebApi().postMessage(botToken, event.channel, text);
    } catch (error) {
      logger.warn(
        { teamId, error: String(error) },
        "Slack unclaimed-workspace connect reply failed",
      );
    }
    return ack;
  }

  extractTeamId(body: string, contentType: string): string | null {
    if (contentType.includes("application/x-www-form-urlencoded")) {
      const params = new URLSearchParams(body);
      const directTeamId = params.get("team_id");
      if (directTeamId) {
        return directTeamId;
      }

      const payloadStr = params.get("payload");
      if (!payloadStr) {
        return null;
      }

      try {
        const payload = JSON.parse(payloadStr) as {
          team?: { id?: string };
          team_id?: string;
        };
        return payload.team?.id || payload.team_id || null;
      } catch {
        return null;
      }
    }

    try {
      const payload = JSON.parse(body) as {
        team_id?: string;
        team?: string;
        event?: { team_id?: string; team?: string };
      };
      return (
        payload.team_id ||
        payload.team ||
        payload.event?.team_id ||
        payload.event?.team ||
        null
      );
    } catch {
