		 AND et.slug = '$member'
		WHERE ei.organization_id = ${organizationId}
		  AND ei.namespace = 'auth_user_id'
		  AND ei.identifier = ${userId}
		  AND ei.deleted_at IS NULL
		  AND ei.source_connector = 'auth:signup'
		LIMIT 1
