396	  async handleAppWebhook(request: Request): Promise<Response> {
397	    const body = await request.text();
398	    const contentType = request.headers.get("content-type") || "";
399	    const teamJoinEvent = parseSlackTeamJoinEvent(body, contentType);
400	    const membershipChangedEvent = parseSlackMembershipChangedEvent(
401	      body,
402	      contentType,
403	    );
404	    const teamId = this.extractTeamId(body, contentType);
405	    // Grid: events for a workspace inside an Enterprise Grid arrive stamped with
406	    // a SIBLING workspace's `team_id` (not the install's), but carry the shared
407	    // `enterprise_id`. Captured so path 2 can fall back to an enterprise match
408	    // when the exact team id misses.
409	    const enterpriseId = this.extractEnterpriseId(body, contentType);
410	
411	    // App/token removal: Slack invalidated the bot token, so stop the matching
412	    // install(s) BEFORE any routing — a still-`active` row would keep routing
413	    // events to a dead token and fail every forward. Ack 200 either way (a
414	    // non-2xx makes Slack retry the uninstall). Handled here (not per-connection)
415	    // because an org-wide uninstall carries only the enterprise id, no team id.
416	    if (isSlackUninstallEvent(body, contentType)) {
417	      const store = this.deps.getAppInstallationStore();
418	      const stopped = await revokeSlackInstallsForUninstall(store, {
419	        teamId,
420	        enterpriseId,
421	      });
422	      logger.info(
423	        { teamId, enterpriseId, stopped },
424	        "Slack app_uninstalled — stopped install(s)",
425	      );
426	      return new Response("", { status: 200 });
427	    }
428	
429	    if (teamId) {
430	      // 1) A BYO agent-owned Slack connection for this workspace (created via
431	      //    the UI with its own bot token) — unchanged legacy path.
432	      const connection = await this.findConnectionByTeamId(teamId);
433	      if (connection) {
434	        if (!(await this.deps.ensureConnectionRunning(connection.id))) {
435	          return new Response("Slack connection unavailable", { status: 503 });
436	        }
437	        return await this.forwardRoutedWebhook(
438	          connection,
439	          request,
440	          body,
441	          teamJoinEvent,
442	          membershipChangedEvent,
443	        );
444	      }
445	    }
446	
447	    // Enterprise Grid interactive payloads can omit `team` entirely and carry
448	    // only the enterprise id. Keep BYO routing team-scoped above, but allow the
449	    // managed-install and pending-install paths to resolve that org-wide key.
450	    const installTenantId = teamId ?? enterpriseId;
451	    if (installTenantId) {
452	      // 2) An OAuth-installed workspace (the "Add to Slack" path). The install
453	      //    is an `app_installations` row (provider=slack), not a BYO `connections` chat row;
454	      //    the manager hydrates an agentless Slack instance from it (the
455	      //    `slackinst-` id is namespaced, so `ensureConnectionRunning`/
456	      //    `forwardWebhook` resolve it via the Slack install projection). Per-message
457	      //    routing is via `/lobu link` bindings.
458	      const store = this.deps.getAppInstallationStore();
459	      // Routing precedence for both install models:
460	      //  a) EXACT team id — a per-workspace install (Grid or standalone) whose
461	      //     own workspace homes this event.
462	      //  b) ORG-WIDE enterprise install — a Grid install with
463	      //     `is_enterprise_install=true` covers EVERY sibling workspace, so a
464	      //     sibling-stamped event routes here by `enterprise_id`. Unambiguous
465	      //     because Slack allows one org-wide install per enterprise, EVEN when
466	      //     per-workspace installs of other siblings also exist.
467	      //  c) SOLE per-workspace Grid install — legacy/self-install fallback for a
468	      //     Grid enterprise that has exactly one (non-org-wide) install and no
469	      //     org-wide one; still by enterprise_id, but only when unambiguous.
470	      const installation =
471	        (teamId ? await getSlackInstallByTeamId(store, teamId) : null) ??
472	        (enterpriseId
473	          ? ((await getSlackEnterpriseInstall(store, enterpriseId)) ??
474	            (await getSlackInstallByEnterpriseId(store, enterpriseId)))
475	          : null);
476	      if (installation && installation.status !== "stopped") {
477	        if (!(await this.deps.ensureConnectionRunning(installation.id))) {
478	          return new Response("Slack connection unavailable", { status: 503 });
479	        }
480	        return await this.forwardRoutedWebhook(
481	          installation,
482	          request,
483	          body,
484	          teamJoinEvent,
485	          membershipChangedEvent,
486	        );
487	      }
488	
489	      // 3) A workspace that installed Lobu but hasn't been CLAIMED into a Lobu
490	      //    org yet (a `pending` install). Don't silently drop their messages —
491	      //    reply with the connect link so a workspace admin can finish setup.
492	      const pending = await resolveSlackPendingByTenant(
493	        installTenantId,
494	        enterpriseId,
495	      );
496	      if (pending) {
497	        return await this.replyUnclaimedWorkspace(
498	          pending.botToken,
499	          // Use the PENDING ROW's own key as the claim ref, not the event's team
500	          // id: for a Grid org-wide install the pending row is keyed on the
501	          // enterprise id, and a sibling-workspace event's team id would not
502	          // resolve the pending row at claim time.
503	          pending.teamId,
504	          body,
505	          contentType,
506	          request.headers.get("x-slack-retry-num") !== null,
507	        );
508	      }
509	    }
510	
511	    const fallbackConnection = await this.getDefaultConnection();
512	    if (fallbackConnection) {
513	      if (!(await this.deps.ensureConnectionRunning(fallbackConnection.id))) {
514	        return new Response("Slack connection unavailable", { status: 503 });
515	      }
516	      return await this.forwardRoutedWebhook(
517	        fallbackConnection,
518	        request,
519	        body,
520	        teamJoinEvent &&
521	          (!fallbackConnection.metadata?.teamId ||
522	            fallbackConnection.metadata.teamId === teamJoinEvent.teamId)
523	          ? teamJoinEvent
524	          : null,
525	        membershipChangedEvent &&
526	          (!fallbackConnection.metadata?.teamId ||
527	            fallbackConnection.metadata.teamId ===
528	              membershipChangedEvent.teamId)
529	          ? membershipChangedEvent
530	          : null,
531	      );
532	    }
533	
534	    const { chat, adapter } = await this.createOAuthChat();
535	    try {
742	        request.method === "GET" || request.method === "HEAD"
743	          ? undefined
744	          : body,
745	    });
746	  }
