748	  /**
749	   * The shared post-verification path for every routed Slack connection. The
750	   * adapter acknowledges only verified webhooks; membership invalidation runs
751	   * after that successful forward and before Lobu returns the acknowledgement.
752	   */
753	  private async forwardRoutedWebhook(
754	    connection: Pick<PlatformConnection, "id" | "organizationId">,
755	    request: Request,
756	    body: string,
757	    teamJoinEvent: ParsedSlackTeamJoinEvent | null,
758	    membershipChangedEvent: ParsedSlackMembershipChangedEvent | null,
759	  ): Promise<Response> {
760	    const response = await this.deps.forwardWebhook(
761	      connection.id,
762	      this.cloneRequestWithBody(request, body),
763	    );
764	    if (!response.ok) return response;
765	
766	    if (membershipChangedEvent) {
767	      if (!connection.organizationId) {
768	        throw new Error(
769	          `Slack membership change for ${connection.id} has no organization scope`,
770	        );
771	      }
772	      const invalidated = await invalidateSlackConnectionAcl({
773	        organizationId: connection.organizationId,
774	        connectionId: connection.id,
775	      });
776	      logger.info(
777	        {
778	          organizationId: connection.organizationId,
779	          connectionId: connection.id,
780	          teamId: membershipChangedEvent.teamId,
781	          channelId: membershipChangedEvent.channelId,
782	          userId: membershipChangedEvent.userId,
783	          eventType: membershipChangedEvent.type,
784	          invalidated,
785	        },
786	        "Slack channel membership changed — invalidated ACL freshness",
787	      );
788	    }
789	    if (teamJoinEvent) {
790	      await this.handleTeamJoinWelcome(connection.id, teamJoinEvent);
791	    }
792	    return response;
793	  }
