610	    payload = JSON.parse(body) as SlackMembershipChangedPayload;
611	  } catch {
612	    return null;
613	  }
614	
615	  const event = payload.event;
616	  if (
617	    payload.type !== "event_callback" ||
618	    (event?.type !== "member_joined_channel" &&
619	      event?.type !== "member_left_channel") ||
620	    !payload.team_id ||
621	    !event.user ||
622	    !event.channel
623	  ) {
624	    return null;
625	  }
626	
627	  return {
628	    type: event.type,
629	    teamId: payload.team_id,
630	    userId: event.user,
631	    channelId: event.channel,
632	  };
633	}
